-- H2-03 Pharma OA inventory and order persistence. Normal uninstall policy: retain.
CREATE TABLE IF NOT EXISTS pharma_oa_stock_batches (id VARCHAR(64) PRIMARY KEY, product_id VARCHAR(64) NOT NULL, batch_no VARCHAR(128) NOT NULL, production_date TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_batches_product_no ON pharma_oa_stock_batches(product_id,batch_no); CREATE INDEX IF NOT EXISTS idx_pharma_batches_expiry ON pharma_oa_stock_batches(expires_at,product_id);
CREATE TABLE IF NOT EXISTS pharma_oa_stock_balances (id VARCHAR(64) PRIMARY KEY, product_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, quantity INTEGER NOT NULL, locked_quantity INTEGER NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_balance_position ON pharma_oa_stock_balances(product_id,warehouse_id,area_id,location_id,batch_id); CREATE INDEX IF NOT EXISTS idx_pharma_balance_warehouse_product ON pharma_oa_stock_balances(warehouse_id,product_id); CREATE INDEX IF NOT EXISTS idx_pharma_balance_batch ON pharma_oa_stock_balances(batch_id);
CREATE TABLE IF NOT EXISTS pharma_oa_stock_ledger (id VARCHAR(64) PRIMARY KEY, operation VARCHAR(32) NOT NULL, reference_id VARCHAR(128) NOT NULL, product_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, quantity_delta INTEGER NOT NULL, balance_after INTEGER NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, idempotency_key VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_ledger_idempotency ON pharma_oa_stock_ledger(idempotency_key); CREATE INDEX IF NOT EXISTS idx_pharma_ledger_reference_time ON pharma_oa_stock_ledger(reference_id,occurred_at); CREATE INDEX IF NOT EXISTS idx_pharma_ledger_position_time ON pharma_oa_stock_ledger(product_id,warehouse_id,batch_id,occurred_at);
CREATE TABLE IF NOT EXISTS pharma_oa_stock_locks (id VARCHAR(64) PRIMARY KEY, balance_id VARCHAR(64) NOT NULL, quantity INTEGER NOT NULL, reason VARCHAR(512) NOT NULL DEFAULT '', status VARCHAR(32) NOT NULL, released_at TIMESTAMPTZ NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE INDEX IF NOT EXISTS idx_pharma_locks_balance_status ON pharma_oa_stock_locks(balance_id,status);
CREATE TABLE IF NOT EXISTS pharma_oa_purchase_requests (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, supplier_id VARCHAR(64) NOT NULL, requester_id VARCHAR(64) NOT NULL, approver_id VARCHAR(64) NOT NULL, reason VARCHAR(1024) NOT NULL DEFAULT '', lines_json TEXT NOT NULL, total_amount NUMERIC(18,2) NOT NULL, status VARCHAR(32) NOT NULL, workflow_instance_id VARCHAR(64) NOT NULL, purchase_order_id VARCHAR(64) NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_purchase_requests_number ON pharma_oa_purchase_requests(number); CREATE INDEX IF NOT EXISTS idx_pharma_purchase_requests_status_approver ON pharma_oa_purchase_requests(status,approver_id); CREATE INDEX IF NOT EXISTS idx_pharma_purchase_requests_supplier ON pharma_oa_purchase_requests(supplier_id);
CREATE TABLE IF NOT EXISTS pharma_oa_purchase_orders (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, purchase_request_id VARCHAR(64) NOT NULL, supplier_id VARCHAR(64) NOT NULL, lines_json TEXT NOT NULL, total_amount NUMERIC(18,2) NOT NULL, status VARCHAR(32) NOT NULL, approved_by VARCHAR(64) NOT NULL, approved_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_purchase_orders_number ON pharma_oa_purchase_orders(number); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_purchase_orders_request ON pharma_oa_purchase_orders(purchase_request_id); CREATE INDEX IF NOT EXISTS idx_pharma_purchase_orders_supplier_status ON pharma_oa_purchase_orders(supplier_id,status);
CREATE TABLE IF NOT EXISTS pharma_oa_purchase_inbounds (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, purchase_order_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, lines_json TEXT NOT NULL, status VARCHAR(32) NOT NULL, received_by VARCHAR(64) NOT NULL, received_at TIMESTAMPTZ NOT NULL, attachments_json TEXT NOT NULL, idempotency_key VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_inbounds_number ON pharma_oa_purchase_inbounds(number); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_inbounds_idempotency ON pharma_oa_purchase_inbounds(idempotency_key); CREATE INDEX IF NOT EXISTS idx_pharma_inbounds_order ON pharma_oa_purchase_inbounds(purchase_order_id);
CREATE TABLE IF NOT EXISTS pharma_oa_sales_orders (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, customer_id VARCHAR(64) NOT NULL, lines_json TEXT NOT NULL, total_amount NUMERIC(18,2) NOT NULL, status VARCHAR(32) NOT NULL, organization_id VARCHAR(64) NOT NULL DEFAULT '', actor_id VARCHAR(64) NOT NULL DEFAULT '', business_created_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_sales_orders_number ON pharma_oa_sales_orders(number); CREATE INDEX IF NOT EXISTS idx_pharma_sales_orders_customer_status ON pharma_oa_sales_orders(customer_id,status); CREATE INDEX IF NOT EXISTS idx_pharma_sales_orders_scope ON pharma_oa_sales_orders(organization_id,created_at);
CREATE TABLE IF NOT EXISTS pharma_oa_sales_outbounds (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, sales_order_id VARCHAR(64) NOT NULL, customer_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, lines_json TEXT NOT NULL, status VARCHAR(32) NOT NULL, shipped_by VARCHAR(64) NOT NULL, shipped_at TIMESTAMPTZ NOT NULL, idempotency_key VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_outbounds_number ON pharma_oa_sales_outbounds(number); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_outbounds_idempotency ON pharma_oa_sales_outbounds(idempotency_key); CREATE INDEX IF NOT EXISTS idx_pharma_outbounds_order ON pharma_oa_sales_outbounds(sales_order_id);
CREATE TABLE IF NOT EXISTS pharma_oa_stocktakes (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, product_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, system_quantity INTEGER NOT NULL, actual_quantity INTEGER NOT NULL, difference INTEGER NOT NULL, reason VARCHAR(1024) NOT NULL DEFAULT '', approver_id VARCHAR(64) NOT NULL, workflow_instance_id VARCHAR(64) NOT NULL, ledger_id VARCHAR(64) NOT NULL DEFAULT '', status VARCHAR(32) NOT NULL, actor_id VARCHAR(64) NOT NULL, approved_by VARCHAR(64) NOT NULL DEFAULT '', business_created_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_stocktakes_number ON pharma_oa_stocktakes(number); CREATE INDEX IF NOT EXISTS idx_pharma_stocktakes_warehouse_status ON pharma_oa_stocktakes(warehouse_id,status);
CREATE TABLE IF NOT EXISTS pharma_oa_transfers (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, product_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, quantity INTEGER NOT NULL, source_warehouse_id VARCHAR(64) NOT NULL, source_area_id VARCHAR(64) NOT NULL, source_location_id VARCHAR(64) NOT NULL, target_warehouse_id VARCHAR(64) NOT NULL, target_area_id VARCHAR(64) NOT NULL, target_location_id VARCHAR(64) NOT NULL, out_ledger_id VARCHAR(64) NOT NULL, in_ledger_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, transferred_by VARCHAR(64) NOT NULL, transferred_at TIMESTAMPTZ NOT NULL, idempotency_key VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_transfers_number ON pharma_oa_transfers(number); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_transfers_idempotency ON pharma_oa_transfers(idempotency_key); CREATE INDEX IF NOT EXISTS idx_pharma_transfers_status ON pharma_oa_transfers(status);
